import { test, expect, type Page } from "@playwright/test";

import { signIn, mockApi, API_URL } from "./fixtures";

/**
 * Campaign page → Invoices panel (components/campaigns/campaign-invoices-panel.tsx,
 * mounted on app/campaigns/view/page.tsx). Since 13 Sep ("invoice will be
 * generated by creator's only") the panel is a list only: no Admin/Plan
 * Maker generator, no per-creator picking. Creators raise from /invoices;
 * Admin approves and Finance marks paid here.
 */
const campaign = {
  id: "camp-1",
  brandName: "Solmate Coffee",
  title: "Launch Week",
  deadline: null,
  createdAt: new Date("2026-01-01").toISOString(),
  costCap: "10000",
  spent: 3000,
  remainingBudget: 7000,
  totalLikes: 0,
  postCount: 4,
  pendingAssignmentCount: 0,
};

function asset(id: string, handle: string, owner: { id: string; name: string; phoneNumber: string }) {
  return {
    id,
    ownerId: owner.id,
    platform: "instagram",
    handle,
    followers: 1000,
    approvalStatus: "approved",
    createdAt: new Date().toISOString(),
    rateCards: [],
    engagement: { avgLikes: null, avgComments: null, avgViews: null, sampleSize: 0 },
    owner,
  };
}
const priya = { id: "creator-1", name: "Priya Creator", phoneNumber: "+919000000001" };
const rahul = { id: "creator-2", name: "Rahul Creator", phoneNumber: "+919000000002" };

function link(id: string, overrides: Record<string, unknown> = {}) {
  return {
    id,
    campaignId: "camp-1",
    assetId: "asset-1",
    submittedById: "creator-1",
    url: `https://instagram.com/p/${id}`,
    format: "reel",
    cost: "1000",
    customRate: false,
    status: "SUBMITTED",
    postedAt: null,
    createdAt: new Date("2026-01-02").toISOString(),
    asset: asset("asset-1", "priya.page", priya),
    ...overrides,
  };
}

// Two of Priya's posts (one already invoiced), one of Rahul's, one broken.
const links = [
  link("l1"),
  link("l2", { cost: "2000" }),
  link("l3", { assetId: "asset-2", asset: asset("asset-2", "rahul.page", rahul), cost: "500" }),
  link("l4", { status: "INVOICED" }),
  link("l5", { status: "INVALID", assetId: "asset-2", asset: asset("asset-2", "rahul.page", rahul) }),
];

async function mockCampaign(page: Page, overrides: { campaign?: Record<string, unknown>; links?: unknown[]; invoices?: unknown[] } = {}) {
  await page.route(`${API_URL}/campaigns/camp-1`, (route) => route.fulfill({ json: { ...campaign, ...(overrides.campaign ?? {}) } }));
  await page.route(`${API_URL}/links?*`, (route) => route.fulfill({ json: { items: overrides.links ?? links, total: (overrides.links ?? links).length, page: 1, pageSize: 100 } }));
  await page.route(`${API_URL}/invoices?*`, (route) => route.fulfill({ json: { items: overrides.invoices ?? [], total: (overrides.invoices ?? []).length, page: 1, pageSize: 100 } }));
}

test.describe("Campaign page — invoices are listed, never generated here (creator-only raising, 13 Sep)", () => {
  test.use({ viewport: { width: 1280, height: 900 } });

  for (const role of ["ADMIN", "PLAN_MAKER", "FINANCE"] as const) {
    test(`${role} sees no invoice generator on the campaign page — no heading, no Generate button, no per-post checkboxes`, async ({ page }) => {
      await signIn(page, role);
      await mockApi(page);
      await mockCampaign(page);
      let generateCalled = false;
      await page.route(`${API_URL}/campaigns/camp-1/invoices`, (route) => {
        generateCalled = true;
        return route.fulfill({ status: 404, json: { error: { code: "NOT_FOUND", message: "gone" } } });
      });

      await page.goto("/campaigns/view?id=camp-1");
      await expect(page.getByRole("heading", { name: "Invoices" })).toBeVisible();
      await expect(page.getByRole("heading", { name: "Generate invoices" })).toHaveCount(0);
      await expect(page.getByRole("button", { name: /Generate( \d+)? invoices?/ })).toHaveCount(0);
      await expect(page.locator("#campaign-invoices").getByRole("checkbox")).toHaveCount(0);
      await expect(page.getByRole("link", { name: "Open Invoices" })).toHaveAttribute("href", "/invoices");
      expect(generateCalled).toBe(false);
    });
  }

  // The old Plans-page chip landed on ?section=invoices; the param still
  // scrolls the (now list-only) Invoices panel into view. A short viewport
  // so the panel really starts below the fold — on a tall one the short
  // page already ends with it in view and there's nothing to scroll.
  test.describe("?section=invoices", () => {
    test.use({ viewport: { width: 1280, height: 640 } });

    test("scrolls the Invoices panel into view on load", async ({ page }) => {
      await signIn(page, "ADMIN");
      await mockApi(page);
      await mockCampaign(page);
      const heading = page.getByRole("heading", { name: "Invoices" });
      const headingY = async () => {
        const box = await heading.boundingBox();
        return box ? box.y : Infinity;
      };

      await page.goto("/campaigns/view?id=camp-1");
      await expect(heading).toBeAttached();
      expect(await headingY()).toBeGreaterThan(640);

      await page.goto("/campaigns/view?id=camp-1&section=invoices");
      await expect(heading).toBeVisible();
      await expect.poll(headingY).toBeLessThan(640);
    });
  });

  test("CREATOR sees only their own invoices for the campaign, with a Raise invoice link to /invoices", async ({ page }) => {
    await signIn(page, "CREATOR");
    await mockApi(page);
    await mockCampaign(page, { invoices: [{
          id: "inv-1",
          creatorId: "creator-1",
          invoiceNumber: "INV-MINE",
          amount: "3540",
          subtotal: "3000",
          isGstInvoice: true,
          gstAmount: "540",
          status: "APPROVED",
          paymentStatus: "PENDING",
          gstStatus: "PENDING",
          remarks: null,
          dueDate: null,
          paidAt: null,
          createdAt: new Date().toISOString(),
          overdueDays: 0,
          campaignId: "camp-1",
          raisedBy: { id: "creator-1", name: "Priya Creator", role: "CREATOR" },
          creator: priya,
          items: [],
        }] });
    await page.goto("/campaigns/view?id=camp-1");
    await expect(page.getByRole("heading", { name: "Generate invoices" })).toHaveCount(0);
    await expect(page.getByRole("link", { name: "Raise invoice" })).toHaveAttribute("href", "/invoices");
    const row = page.getByTestId("campaign-invoice-inv-1");
    await expect(row).toContainText("INV-MINE");
    await expect(row).toContainText("Approved");
    await expect(row).toContainText("Raised by creator");
    await expect(row.getByRole("button", { name: "Mark paid" })).toHaveCount(0);
  });

  test("FINANCE marks a campaign invoice paid from the campaign page — opens the same TDS + mandatory-receipt PaySheet the Payments tab uses (28 Sep)", async ({ page }) => {
    await signIn(page, "FINANCE");
    await mockApi(page);
    await mockCampaign(page, {
      invoices: [
        {
          id: "inv-1",
          creatorId: "creator-1",
          invoiceNumber: "INV-1",
          amount: "500",
          subtotal: "500",
          isGstInvoice: false,
          gstAmount: "0",
          status: "APPROVED",
          paymentStatus: "PENDING",
          gstStatus: "PENDING",
          remarks: null,
          dueDate: null,
          paidAt: null,
          createdAt: new Date().toISOString(),
          overdueDays: 0,
          creator: priya,
          items: [{ id: "ii-1", amount: "500", link: link("l1") }],
        },
      ],
    });
    let created: Record<string, unknown> | null = null;
    await page.route(`${API_URL}/fake-cloudinary`, (route) => route.fulfill({ json: { ok: true } }));
    await page.route(`${API_URL}/payments/**`, (route) => {
      const url = new URL(route.request().url());
      const path = url.pathname.replace("/api/payments", "");
      const method = route.request().method();
      if (method === "POST" && path === "/payouts") {
        created = route.request().postDataJSON();
        return route.fulfill({ status: 201, json: { id: "p-1", creatorId: "creator-1", subtotal: "500", isGstInvoice: false, gstAmount: "0", tdsPercent: null, tdsAmount: "0", netAmount: "500", status: "DRAFT", paidAt: null, createdAt: new Date().toISOString(), creator: priya, items: [] } });
      }
      if (method === "GET" && path === "/payouts/p-1/receipt-upload") {
        return route.fulfill({ json: { uploadUrl: `${API_URL}/fake-cloudinary`, apiKey: "k", timestamp: 1, signature: "s", publicId: "payout-receipts/p-1/uuid" } });
      }
      if (method === "POST" && path === "/payouts/p-1/receipt") {
        return route.fulfill({ status: 201, json: { id: "p-1", creatorId: "creator-1", subtotal: "500", isGstInvoice: false, gstAmount: "0", tdsPercent: null, tdsAmount: "0", netAmount: "500", status: "PAID", paidAt: new Date().toISOString(), createdAt: new Date().toISOString(), creator: priya, items: [] } });
      }
      return route.fallback();
    });

    await page.goto("/campaigns/view?id=camp-1");
    await expect(page.getByRole("heading", { name: "Generate invoices" })).toHaveCount(0);
    await page.getByTestId("campaign-invoice-inv-1").getByRole("button", { name: "Mark paid" }).click();

    const sheet = page.getByTestId("pay-sheet");
    await expect(sheet.getByTestId("pay-sheet-invoices")).toContainText("INV-1");
    await sheet.getByLabel("Payment receipt").setInputFiles({ name: "receipt.pdf", mimeType: "application/pdf", buffer: Buffer.from("%PDF-1.4\n%mock\n") });
    await sheet.getByRole("button", { name: /Mark paid/ }).click();
    await expect(page.getByTestId("payout-paid")).toBeVisible();

    expect(created).toMatchObject({ creatorId: "creator-1", linkIds: [], invoiceIds: ["inv-1"] });
  });
});
